    "statement": {
      "hi": "सोल 3.0 बैकएंड डेटाबेस के रूप में माइक्रोसॉफ्ट एसक्यूएल सर्वर (MS SQL Server) अथवा मायएसक्यूएल (MySQL) का उपयोग करता है।",
      "en": "SOUL 3.0 operates on Microsoft SQL Server or MySQL as its backend relational database management system."
    },
    "tag": "Tech Stack",
