      "hi": "आरआरआरएलएफ पुस्तकालय अनुसंधान को बढ़ावा देने के लिए 'ग्रंथना' (Granthana - अर्धवार्षिक शोध पत्रिका) तथा लोक पुस्तकालयों के समाचारों के लिए 'RRRLF Newsletter' का प्रकाशन करता है।",
      "en": "RRRLF publishes 'Granthana' (a bi-annual peer-reviewed journal on library studies) and the quarterly informational 'RRRLF Newsletter'."
