      "hi": "DDC में 'पुस्तकालय विज्ञान' को '020', 'भौतिकी' को '530' तथा 'पुस्तकालयों में पुस्तक जिल्दसाजी के प्रकार' को '686.3' के तहत वर्गीकृत किया जाता है।",
      "en": "In DDC, 'Library Science' is classified under '020', 'Physics' under '530', and 'Types of Book Binding' under '686.3'."
