      "hi": "डॉ. रंगनाथन की कोलन क्लासिफिकेशन (CC) पद्धति में मुख्य वर्ग '1' (Main Class 1) को विशेष रूप से 'ज्ञान जगत' (Universe of Knowledge) के लिए आबंटित किया गया है।",
      "en": "In Dr. Ranganathan's Colon Classification (CC), Main Class '1' is specifically allocated for the 'Universe of Knowledge'."
