    "categoryKey": "u4_t3",
    "topic": {
      "hi": "टॉपिक 4.3: परिग्रहण रजिस्टर (Accession Register)",
      "en": "Topic 4.3: Accession Register"
    },
    "statement": {
      "hi": "परिग्रहण रजिस्टर पुस्तकालय का स्थायी कानूनी अभिलेख है; इसका मानक आकार 16 × 13 इंच होता है और इसमें 14 से 15 मानक स्तंभ (Columns) होते हैं।",
      "en": "Accession Register is the permanent legal ledger measuring 16 x 13 inches with 14 to 15 standardized columns."
    },
    "tag": "Operational Norm",
