    "statement": {
      "hi": "इनसाइक्लोपीडिया ब्रिटानिका का प्रथम संस्करण 1768 में एडिनबर्ग (स्कॉटलैंड) में प्रकाशित हुआ था। 2012 से इसका मुद्रित प्रकाशन बंद हो गया।",
      "en": "The first edition of Encyclopaedia Britannica was published in 1768 in Edinburgh, Scotland. Print editions ceased in 2012."
    },
